// ============================================================
// PRE-REQUEST — RF-G9-01 Reporte de movimientos agrupados
// Todas las variables viven en pm.collectionVariables
// ============================================================

const sqlBaseUrl = pm.collectionVariables.get('sqlSandboxBaseUrl');
const sqlApiKey  = pm.collectionVariables.get('sqlSandboxApiKey');

function querySandbox(sql, params, callback) {
    pm.sendRequest({
        url: `${sqlBaseUrl}/api/v1/sql/select`,
        method: 'POST',
        header: {
            'Content-Type': 'application/json',
            'x-api-key': sqlApiKey
        },
        body: {
            mode: 'raw',
            raw: JSON.stringify({ sql, params: params || [] })
        }
    }, (err, res) => {
        if (err) return callback(err, null);
        if (res.code !== 200) {
            return callback(new Error(`SQL ${res.code}: ${JSON.stringify(res.json())}`), null);
        }
        callback(null, res.json().data || []);
    });
}

// PASO 1 — elegir usuarioId con movimientos reales
querySandbox(
    `SELECT usuario_id, COUNT(*) AS total_movs
     FROM movimientos
     GROUP BY usuario_id
     ORDER BY total_movs DESC
     LIMIT 1`,
    [],
    (err, rows) => {
        if (err) {
            console.error('❌ Pre-request paso 1 falló:', err.message);
            pm.execution.skipRequest();
            return;
        }
        if (!rows.length) {
            console.warn('⚠️ No hay movimientos; se aborta el request');
            pm.execution.skipRequest();
            return;
        }

        const usuarioId = rows[0].usuario_id;
        pm.collectionVariables.set('g9_usuario_id', usuarioId);
        pm.collectionVariables.set('g9_movs_esperados', Number(rows[0].total_movs));
        console.log(`✅ usuarioId capturado: ${usuarioId} (${rows[0].total_movs} movimientos)`);

        // PASO 2 — rango real de fechas
        querySandbox(
            `SELECT MIN(created_at) AS desde, MAX(created_at) AS hasta
             FROM movimientos
             WHERE usuario_id = $1`,
            [usuarioId],
            (err2, rows2) => {
                if (err2) {
                    console.error('❌ Pre-request paso 2 falló:', err2.message);
                    pm.execution.skipRequest();
                    return;
                }

                if (rows2.length) {
                    pm.collectionVariables.set('g9_desde', rows2[0].desde);
                    pm.collectionVariables.set('g9_hasta', rows2[0].hasta);
                    console.log(`✅ Rango: ${rows2[0].desde} → ${rows2[0].hasta}`);
                }

                // PASO 3 — tipos de movimiento esperados
                querySandbox(
                    `SELECT DISTINCT tipo_movimiento
                     FROM movimientos
                     WHERE usuario_id = $1`,
                    [usuarioId],
                    (err3, rows3) => {
                        if (err3) {
                            console.error('❌ Pre-request paso 3 falló:', err3.message);
                            pm.execution.skipRequest();
                            return;
                        }
                        const tipos = rows3.map(r => r.tipo_movimiento);
                        pm.collectionVariables.set('g9_tipos_esperados', JSON.stringify(tipos));
                        console.log(`✅ Tipos: ${tipos.join(', ')}`);
                    }
                );
            }
        );
    }
);

// ============================================================
// POST-REQUEST — RF-G9-01 (v2 — fixes tipo string)
// ============================================================

const sqlBaseUrl    = pm.collectionVariables.get('sqlSandboxBaseUrl');
const sqlApiKey     = pm.collectionVariables.get('sqlSandboxApiKey');
const usuarioId     = pm.collectionVariables.get('g9_usuario_id');
const movsEsperados = Number(pm.collectionVariables.get('g9_movs_esperados'));
const tiposEsperados = JSON.parse(pm.collectionVariables.get('g9_tipos_esperados') || '[]');

function querySandbox(sql, params, callback) {
    pm.sendRequest({
        url: `${sqlBaseUrl}/api/v1/sql/select`,
        method: 'POST',
        header: { 'Content-Type': 'application/json', 'x-api-key': sqlApiKey },
        body: {
            mode: 'raw',
            raw: JSON.stringify({ sql, params: params || [] })
        }
    }, (err, res) => {
        if (err) return callback(err, null);
        if (res.code !== 200) {
            return callback(new Error(`SQL ${res.code}: ${JSON.stringify(res.json())}`), null);
        }
        callback(null, res.json());
    });
}

// --- AC-G9-01a: Status ---
pm.test("AC-G9-01a: Status 200", () => {
    pm.response.to.have.status(200);
});

const jsonData = pm.response.json();

pm.test("AC-G9-01a: Devuelve array de agregados", () => {
    pm.expect(jsonData.data).to.be.an('array');
    pm.expect(jsonData.data.length).to.be.at.least(1);
});

pm.test("AC-G9-01a: Cada item tiene tipo_movimiento, cantidad y total", () => {
    jsonData.data.forEach((item, i) => {
        pm.expect(item, `item[${i}]`).to.have.property('tipo_movimiento');
        pm.expect(item, `item[${i}]`).to.have.property('cantidad');
        pm.expect(item, `item[${i}]`).to.have.property('total');

        // ✅ Postgres devuelve NUMERIC como string
        pm.expect(item.cantidad, `cantidad[${i}]`).to.be.a('string');
        pm.expect(item.total, `total[${i}]`).to.be.a('string');
        pm.expect(isNaN(parseFloat(item.cantidad))).to.be.false;
        pm.expect(isNaN(parseFloat(item.total))).to.be.false;
    });
});

pm.test("AC-G9-01a: Los tipos devueltos son los esperados según DB", () => {
    const tiposRecibidos = jsonData.data.map(i => i.tipo_movimiento);
    tiposEsperados.forEach(tipo => {
        pm.expect(tiposRecibidos).to.include(tipo);
    });
});

// --- AC-G9-01b: filtro por usuarioId (COUNT cruzado con DB) ---
pm.test("AC-G9-01b: Suma de cantidades == COUNT(*) en DB", function (done) {
    const sumaCantidades = jsonData.data.reduce(
        (acc, x) => acc + Number(x.cantidad), 0
    );

    querySandbox(
        `SELECT COUNT(*) AS total FROM movimientos WHERE usuario_id = $1`,
        [usuarioId],
        (err, res) => {
            if (err) {
                done(err);
                return;
            }
            const rows = res.data || [];
            const totalDB = Number(rows[0].total);

            pm.expect(sumaCantidades, 
                `suma response=${sumaCantidades} vs COUNT DB=${totalDB}`
            ).to.eql(totalDB);

            pm.expect(totalDB).to.eql(movsEsperados,
                `COUNT DB=${totalDB} vs capturado=${movsEsperados}`
            );
            done();
        }
    );
});

// --- AC-G9-01c: rango desde/hasta ---
pm.test("AC-G9-01c: Suma con rango == COUNT(*) con rango en DB", function (done) {
    const desde = pm.collectionVariables.get('g9_desde');
    const hasta = pm.collectionVariables.get('g9_hasta');
    const sumaCantidades = jsonData.data.reduce(
        (acc, x) => acc + Number(x.cantidad), 0
    );

    querySandbox(
        `SELECT COUNT(*) AS total
         FROM movimientos
         WHERE usuario_id = $1
           AND created_at >= $2
           AND created_at <= $3`,
        [usuarioId, desde, hasta],
        (err, res) => {
            if (err) {
                done(err);
                return;
            }
            const rows = res.data || [];
            const totalDBRango = Number(rows[0].total);

            pm.expect(sumaCantidades,
                `suma response=${sumaCantidades} vs COUNT con rango=${totalDBRango}`
            ).to.eql(totalDBRango);
            done();
        }
    );
});

// --- AC-G9-01c: totales por tipo coinciden con DB ---
pm.test("AC-G9-01c: Totales por tipo coinciden con DB", function (done) {
    querySandbox(
        `SELECT tipo_movimiento, COUNT(*) AS cantidad, SUM(monto) AS total
         FROM movimientos
         WHERE usuario_id = $1
         GROUP BY tipo_movimiento
         ORDER BY tipo_movimiento`,
        [usuarioId],
        (err, res) => {
            if (err) {
                done(err);
                return;
            }
            const rows = res.data || [];

            const dbPorTipo = {};
            rows.forEach(r => {
                dbPorTipo[r.tipo_movimiento] = {
                    cantidad: Number(r.cantidad),
                    total: Number(r.total)      // ✅ normalizado
                };
            });

            jsonData.data.forEach(item => {
                const db = dbPorTipo[item.tipo_movimiento];
                pm.expect(db, 
                    `Tipo ${item.tipo_movimiento} debe existir en DB`
                ).to.exist;

                pm.expect(Number(item.cantidad),
                    `cantidad de ${item.tipo_movimiento}`
                ).to.eql(db.cantidad);

                pm.expect(parseFloat(item.total),
                    `total de ${item.tipo_movimiento}`
                ).to.eql(db.total);
            });
            done();
        }
    );
});

